        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Containers", "Register a reusable container type",
                "Register the layout once and keep its ContainerType instance. A per-slot allowlist overrides the container-wide rule: omit the slot's allowedItems field to inherit it, or pass an empty array to allow every item in that slot. Slots missing from the array inherit the container-wide rule. Reference the type from a scripted block with its id. Lua-style lower-camel fields are canonical; Rows, Title, AllowedItems, and Slots are accepted aliases.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal machine = Registry.Containers:Register(\"crusher\", {\n    rows = 2,\n    title = \"Crusher\",\n    allowedItems = { \"minecraft:iron_ore\", \"minecraft:raw_iron\" },\n    slots = {\n        { allowedItems = { \"minecraft:iron_ore\", \"minecraft:raw_iron\" } },\n        { allowedItems = { \"minecraft:coal\" } },\n        { allowedItems = {} }, -- explicit empty list allows every item in this slot\n    },\n})\n\nprint(machine.Id, machine.SlotCount)\nprint(machine:AllowsItemInSlot(1, \"minecraft:iron_ore\"))\nprint(machine:AllowsItemInSlot(3, \"minecraft:diamond\"))\nlocal registered = Registry.Containers:Get(machine.Id)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Containers", "Attach the registered type to a block",
                "Pass the ContainerType instance or its id. MLua retains the registered layout and every slot rule, then opens the vanilla container screen when the block is used. Add an onRightClick callback only when you need custom server logic before it opens.",
                "Registry.Blocks:Register(\"crusher_block\", {\n    strength = 2,\n    container = machine, -- the ContainerType instance\n})\n\n-- A namespaced id works too:\n-- container = machine.Id"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Blocks", "Build a block entity and container with BlockProperties",
                "BlockProperties accepts the same container and blockEntity definitions as Registry.Blocks:Register. Container stores either a registered container id or a copied inline definition. BlockEntity snapshots a class name and lifecycle callbacks, so changing the source table after the call cannot change the registration.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nMinecraft:RegisterClass(\"RuneChestEntity\", \"BlockEntity\", \"Persistent state for a rune chest.\")\n\nlocal block = Block.Properties()\n    :Strength(3, 6)\n    :Container({ rows = 3, title = \"Rune Chest\" })\n    :BlockEntity({\n        className = \"RuneChestEntity\",\n        onLoad = function(self, context)\n            self.Nbt.charge = self.Nbt.charge or 0\n        end,\n    })\n\nRegistry.Blocks:Register(\"rune_chest\", block)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Blocks", "Register a block and its item",
                "Register the block first, then register its item form. Each call returns a RegistryEntry key you can keep for later lookup or to check registration state. The block definition accepts Minecraft block properties and scripted callbacks; the item definition accepts stack, durability, food, rarity, and item callbacks.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal block = Registry.Blocks:Register(\"signal_block\", {\n    strength = 3,\n    resistance = 6,\n    sound = \"stone\",\n    mapColor = \"stone\",\n    requiresCorrectTool = true,\n    onRightClick = function(context)\n        context.Player:SendMessage(\"The block answers with a quiet hum.\")\n        return true\n    end,\n})\n\nlocal item = Registry.Blocks:RegisterItem(\"signal_block\", {\n    maxStackSize = 16,\n    rarity = \"uncommon\",\n    description = \"A block that listens for a signal.\",\n})\n\nprint(block.Id, item.Id)\nprint(table.concat(Registry.Blocks:GetSounds(), \", \"))\nprint(table.concat(Registry.Items:GetRarities(), \", \"))"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Items", "Use Minecraft-style property chains",
                "ItemProperties and BlockProperties are real Lua classes with inherited common settings. Their chainable methods map to native Minecraft properties, and the same instances can be passed directly to Register. Texture accepts a resource id or a block face map; relative texture names resolve under textures/item or textures/block. Model accepts a model resource id. Both can be shipped as normal addon assets. Build returns a plain table when you need to add or inspect fields yourself.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal sword = Item.Properties()\n    :Kind(\"sword\")\n    :Tier(\"iron\")\n    :Durability(420)\n    :AttackDamage(7)\n    :AttackSpeed(1.4)\n    :Rarity(\"uncommon\")\n    :Texture(\"horror:scratched_iron\")\n    :Model(\"horror:scratched_iron\")\n    :OnUse(function(context)\n        context.Player:SendMessage(\"The blade answers.\")\n    end)\n\nRegistry.Items:Register(\"signal_sword\", sword)\n\nlocal block = Block.Properties()\n    :Strength(3, 6)\n    :Texture({\n        top = \"horror:signal_block_top\",\n        bottom = \"horror:signal_block_bottom\",\n        north = \"horror:signal_block_side\",\n        south = \"horror:signal_block_side\",\n        east = \"horror:signal_block_side\",\n        west = \"horror:signal_block_side\",\n    })\n    :Model(\"horror:signal_block\")\n    :Sound(\"stone\")\n    :RequiresCorrectToolForDrops(true)\n    :OnRightClick(function(context)\n        context.Player:SendMessage(\"The block answers.\")\n        return true\n    end)\n\nRegistry.Blocks:Register(\"signal_block\", block)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry", "Use the shared registration entry point",
                "Registry:Register routes definitions through the typed registries for items, blocks, entities, effects, potions, particles, containers, projectiles, world generation, tabs, recipes, loot, tags, common config, and damage sources. Use block_item after registering its block; register a tag as Registry:Register(\"tag\", kind, name, definition). RegisterType defines reusable addon-scoped defaults for each category. Items select them with kind, blocks with type, and other categories with RegistryType. Use Registry.ContentTypes for reusable defaults in your own data domains. GetRegistered returns IDs visible for a Minecraft registry kind.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nRegistry:Register(\"item\", \"flare_gun\", {\n    kind = \"firearm\",\n    maxStackSize = 1,\n    onUse = function(context)\n        -- Use the live player and projectile services here.\n    end,\n})\n\nfor _, id in ipairs(Registry:GetRegistered(\"items\")) do\n    print(id)\nend"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry", "Add an addon-owned registry category",
                "RegisterCategory adds a category under your addon's namespace (for example, 'horror:weapons'). Its handler receives each namespaced id and resolved definition during the registry phase. Categories support inherited content types and sorted typed handle lookups. Limits are 256 addon categories, 16,384 entries per category, 65,536 entries across the runtime, 128 concurrent registrations per category, and 16,384 table entries per definition at a nesting depth of up to 64.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nRegistry:RegisterCategory(\"horror:weapons\", \"Weapon tuning data owned by this addon.\", function(id, definition)\n    if definition.Damage <= 0 then\n        error(\"Weapon damage must be positive\")\n    end\nend)\n\nRegistry:RegisterType(\"horror:weapons\", \"sidearm\", {\n    Base = \"default\",\n    Defaults = { Damage = 8, MagazineSize = 6 },\n})\n\nRegistry:Register(\"horror:weapons\", \"revolver\", {\n    RegistryType = \"sidearm\",\n    Damage = 12,\n})\n\nlocal revolver = Registry:Get(\"horror:weapons\", \"horror:revolver\")\nprint(revolver.Id, revolver.Definition.Damage)\nlocal weapons = Registry:GetCategory(\"horror:weapons\")\nfor _, id in ipairs(weapons:GetIds(\"horror\")) do\n    print(id)\nend\nfor id, weapon in pairs(Registry:GetAll(\"horror:weapons\")) do\n    print(id, weapon.Definition.Damage)\nend\n\nlocal entry = weapons:GetEntry(\"horror:revolver\")\nif entry and entry.IsRegistered then\n    print(entry.Owner, entry.Definition.Damage)\nend\nfor _, registered in ipairs(weapons:GetEntries(\"horror\")) do\n    print(registered.Id, registered.CategoryDescription)\nend"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.ContentTypes", "Define types for addon data",
                "ContentTypes lets an addon reuse inherited defaults and descriptions outside Minecraft's built-in categories. Give each domain a stable name, register its types during the registry phase, then resolve definitions with RegistryType. A child snapshots its parent's defaults when it is registered, so it remains usable if the parent addon unloads. A definition without a selector passes through unchanged; a named type that is missing from that domain raises an error. Each runtime allows up to "
                    + dev.mlua.runtime.registry.MLuaContentTypeRegistry.MAX_TYPES_PER_DOMAIN + " types per domain and "
                    + dev.mlua.runtime.registry.MLuaContentTypeRegistry.MAX_TYPES_PER_SCOPE + " total; defaults and resolved definitions are limited to "
                    + dev.mlua.runtime.registry.MLuaContentTypeRegistry.MAX_DEFAULT_ENTRIES_PER_TYPE + " table entries and "
                    + dev.mlua.runtime.registry.MLuaContentTypeRegistry.MAX_TABLE_DEPTH + " nested tables.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nRegistry.ContentTypes:Register(\"horror.weapon\", \"sidearm\", {\n    Base = \"default\",\n    Description = \"Shared defaults for compact horror weapons.\",\n    Defaults = { Damage = 6, Magazine = { Size = 8, ReloadTicks = 30 } },\n})\n\nRegistry.ContentTypes:Register(\"horror.weapon\", \"revolver\", {\n    Base = \"sidearm\",\n    Description = \"A slow, powerful revolver.\",\n    Defaults = { Damage = 12, Magazine = { Size = 6 } },\n})\n\nlocal weapon = Registry.ContentTypes:Resolve(\"horror.weapon\", {\n    RegistryType = \"revolver\",\n    Damage = 14,\n})\nprint(weapon.Damage, weapon.Magazine.Size, weapon.Magazine.ReloadTicks)"));
        docs.register(MLuaDocBuilder.Registration.signature("Registry.ContentTypes",
            "Registry.ContentTypes:GetLimits(domain: string)", "ContentTypeLimits"));
        docs.register(MLuaDocBuilder.Registration.type("ContentTypeLimits", null,
            "Active reusable type counts and capacity limits for one runtime."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "ActiveInDomain", "number",
            "Number of types currently registered in the requested domain."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "ActiveTotal", "number",
            "Number of types currently registered across all domains in the runtime."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "MaxPerDomain", "number",
            "Maximum registered types in one domain."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "MaxTotal", "number",
            "Maximum registered types across all domains in the runtime."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "MaxEntriesPerType", "number",
            "Maximum table entries in defaults or a resolved definition."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "ActiveDefaultTableEntries", "number",
            "Nested default table entries currently stored by reusable content types in this runtime."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "AddonDefaultTableEntries", "number",
            "Nested default table entries currently stored by this addon's reusable content types."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "MaxDefaultTableEntriesPerAddon", "number",
            "Maximum nested default table entries stored across one addon's reusable content types."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "MaxDefaultTableEntriesTotal", "number",
            "Maximum nested default table entries stored across all reusable content types in this runtime."));
        docs.register(MLuaDocBuilder.Registration.field("ContentTypeLimits", "MaxNestingDepth", "number",
            "Maximum nested table depth in defaults or a resolved definition."));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry", "Attach Lua classes to items and blocks",
                "Register a class under Item or Block, then set className in the content definition. Callback contexts receive live instances of that class, including inherited methods and applied mixins.",
                "Minecraft:RegisterClass(\"HuntingBow\", \"Item\", \"A reusable hunting bow.\")\nMinecraft:RegisterClassFunction(\"HuntingBow\", \"IsReady\", function(self)\n    return self:GetDamage() < self:GetMaxDamage()\nend, \"Checks whether the bow can still be used.\")\n\nMinecraft:RegisterClass(\"HauntedSoil\", \"Block\", \"Soil that reacts to nearby players.\")\nMinecraft:RegisterClassFunction(\"HauntedSoil\", \"Collapse\", function(self)\n    self:Set(\"minecraft:air\")\nend, \"Removes this soil block.\")\n\nRegistry.Items:Register(\"hunting_bow\", { className = \"HuntingBow\" })\nRegistry.Blocks:Register(\"haunted_soil\", { className = \"HauntedSoil\" })"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.DataPack", "Register data-driven world generation",
                "WorldGeneration writes vanilla dimension, dimension_type, and worldgen resources into the addon's namespace. Use the named registration methods for biomes, dimensions, terrain settings, carvers, features, and structures. Use Register for less common resource paths. Definitions use Minecraft's version-specific data format and can inherit reusable defaults through RegistryType. Generated data is limited to 65,536 resources globally and 16,384 per addon; each definition can contain at most 16,384 total entries, 64 nested tables, and 1,048,576 characters of string content.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nRegistry.DataPack:RegisterType(\"tree_feature\", {\n    Base = \"default\",\n    Description = \"Shared placement settings for this addon's trees.\",\n    Defaults = { type = \"minecraft:tree\" },\n})\n\nRegistry.DataPack:Register(\"worldgen/configured_feature\", \"dead_oak\", {\n    RegistryType = \"tree_feature\",\n    config = {\n        dirt_provider = { type = \"minecraft:simple_state_provider\", state = { Name = \"minecraft:dirt\" } },\n        trunk_provider = { type = \"minecraft:simple_state_provider\", state = { Name = \"minecraft:oak_log\" } },\n        foliage_provider = { type = \"minecraft:simple_state_provider\", state = { Name = \"minecraft:oak_leaves\", Properties = { distance = \"7\", persistent = \"false\" } } },\n        trunk_placer = { type = \"minecraft:straight_trunk_placer\", base_height = 4, height_rand_a = 2, height_rand_b = 0 },\n        foliage_placer = { type = \"minecraft:blob_foliage_placer\", radius = 2, offset = 0, height = 3 },\n        minimum_size = { type = \"minecraft:two_layers_feature_size\", limit = 1, lower_size = 0, upper_size = 1 },\n        decorators = {},\n    },\n})\n\nRegistry.DataPack:Register(\"worldgen/placed_feature\", \"dead_oak\", {\n    feature = \"myaddon:dead_oak\",\n    placement = {\n        { type = \"minecraft:count\", count = 1 },\n        { type = \"minecraft:in_square\" },\n        { type = \"minecraft:heightmap\", heightmap = \"WORLD_SURFACE_WG\" },\n        { type = \"minecraft:biome\" },\n    },\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Assets", "Contribute to an asset JSON file",
                "Register one or more top-level keys in an addon asset path such as sounds.json. Calls for the same path merge when their keys differ; duplicate keys fail. The method returns the full namespaced resource path. MLua allows 16,384 files globally, 4,096 per addon, and 16,384 top-level keys per file. Each contribution is limited to 16,384 table entries and 1,048,576 characters of string content; raw JSON strings are also limited to 1,048,576 characters.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal path = Registry.Assets:Register(\"sounds.json\", {\n    haunted_whisper = {\n        sounds = { \"mlua:haunted_whisper\" },\n    },\n})\nprint(path) -- myaddon:sounds.json"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.WorldGeneration", "Place an ore, tree, or plant in selected biomes",
                "Use a biome id or tag selector with the same API on Fabric, Forge, and NeoForge. The placed feature must already be registered as a data pack resource. Set step to a string or an Enum.GenerationStep.Decoration value; both forms are validated against Minecraft's decoration stages.",
                "Registry.WorldGeneration:AddFeature(\"dead_oak_forest\", {\n    feature = \"myaddon:dead_oak\",\n    biomes = { \"#minecraft:is_forest\" },\n    step = Enum.GenerationStep.Decoration.VegetalDecoration,\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.WorldGeneration", "Define a biome, dimension, or terrain resource",
                "register writes a canonical Minecraft data resource to the generated server pack and returns its namespaced id. resourceType is an open path: use dimension, dimension_type, or any worldgen/* registry path such as worldgen/biome, worldgen/noise_settings, and worldgen/density_function. IDs are owned by the addon namespace. These definitions are version-specific Minecraft JSON and are loaded when the generated data pack is enabled.",
                "local WorldGeneration = Minecraft:GetService(\"Registry\").WorldGeneration\n\nWorldGeneration:Register(\"worldgen/biome\", \"ashen_marsh\", {\n    has_precipitation = true,\n    temperature = 0.7,\n    downfall = 0.9,\n    effects = {\n        fog_color = 12638463,\n        water_color = 4159204,\n        water_fog_color = 329011,\n        sky_color = 7907327,\n    },\n    spawners = {},\n    spawn_costs = {},\n    carvers = {},\n    features = {},\n})\n\nWorldGeneration:Register(\"dimension_type\", \"ashen_depths\", {\n    ultrawarm = false,\n    natural = false,\n    coordinate_scale = 1.0,\n    has_skylight = false,\n    has_ceiling = true,\n    ambient_light = 0.1,\n    logical_height = 256,\n    infiniburn = \"minecraft:infiniburn_overworld\",\n    effects = \"minecraft:the_nether\",\n    min_y = -64,\n    height = 384,\n    monster_spawn_block_light_limit = 0,\n    monster_spawn_light_level = { type = \"minecraft:uniform\", value = { min_inclusive = 0, max_inclusive = 7 } },\n})\n\nWorldGeneration:Register(\"dimension\", \"ashen_depths\", {\n    type = \"myaddon:ashen_depths\",\n    generator = {\n        type = \"minecraft:noise\",\n        settings = \"myaddon:ashen_depths\",\n        biome_source = {\n            type = \"minecraft:fixed\",\n            biome = \"myaddon:ashen_marsh\",\n        },\n    },\n})\n\nWorldGeneration:Register(\"worldgen/noise_settings\", \"ashen_depths\", {\n    sea_level = 32,\n    disable_mob_generation = false,\n    aquifers_enabled = true,\n    ore_veins_enabled = false,\n    legacy_random_source = false,\n    default_block = { Name = \"minecraft:deepslate\" },\n    default_fluid = { Name = \"minecraft:lava\" },\n    noise = { min_y = -64, height = 384, size_horizontal = 1, size_vertical = 2 },\n    noise_router = {\n        barrier = \"minecraft:overworld/barrier\",\n        fluid_level_floodedness = \"minecraft:overworld/fluid_level_floodedness\",\n        fluid_level_spread = \"minecraft:overworld/fluid_level_spread\",\n        lava = \"minecraft:overworld/lava\",\n        temperature = \"minecraft:overworld/temperature\",\n        vegetation = \"minecraft:overworld/vegetation\",\n        continents = \"minecraft:overworld/continents\",\n        erosion = \"minecraft:overworld/erosion\",\n        depth = \"minecraft:overworld/depth\",\n        ridges = \"minecraft:overworld/ridges\",\n        initial_density_without_jaggedness = \"minecraft:overworld/initial_density_without_jaggedness\",\n        final_density = \"minecraft:overworld/final_density\",\n        vein_toggle = \"minecraft:overworld/vein_toggle\",\n        vein_ridged = \"minecraft:overworld/vein_ridged\",\n        vein_gap = \"minecraft:overworld/vein_gap\",\n    },\n    spawn_target = {},\n    surface_rule = { type = \"minecraft:block\", result_state = { Name = \"minecraft:deepslate\" } },\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.WorldGeneration", "Use named terrain resource methods",
                "Named methods fix the Minecraft data path, return the full namespaced id, and use the same inherited worldgen defaults as Register. For anything outside these common resource kinds, keep using Register with the resource path.",
                "local WorldGeneration = Minecraft:GetService(\"Registry\").WorldGeneration\n\nWorldGeneration:RegisterBiome(\"ashen_marsh\", biomeDefinition)\nWorldGeneration:RegisterDimensionType(\"ashen_depths\", dimensionTypeDefinition)\nWorldGeneration:RegisterDimension(\"ashen_depths\", dimensionDefinition)\nWorldGeneration:RegisterNoiseSettings(\"ashen_depths\", noiseSettings)\nWorldGeneration:RegisterDensityFunction(\"ashen_depths/caves\", densityFunction)\nWorldGeneration:RegisterStructure(\"buried_station\", structureDefinition)\nWorldGeneration:RegisterStructureSet(\"buried_station\", structurePlacement)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Recipes", "Register a cooking recipe",
                "RegisterCooking accepts smelting, blasting, smoking, or campfire_cooking. Ingredient input can be an item id, a #tag selector, or an item/tag table; MLua validates it and writes the version-specific format. Result fields are also converted for the target. Use Register for a custom recipe type or any schema MLua does not build directly.",
                "local Recipes = Minecraft:GetService(\"Registry\").Recipes\n\nRecipes:RegisterCooking(\"raw_ore_blasting\", \"blasting\", {\n    ingredient = { item = \"myaddon:raw_ore\" },\n    result = \"myaddon:ingot\",\n    experience = 0.7,\n    cookingTime = 100,\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Recipes", "Register shaped and shapeless crafting recipes",
                "Use RegisterShaped for a 1-to-3 row pattern and RegisterShapeless for one-to-nine ingredients. Ingredient definitions can be item ids, #tag selectors, or items lists. MLua validates the pattern, missing or unused keys, result id, and count, then writes the recipe format for the active Minecraft target.",
                "local Recipes = Minecraft:GetService(\"Registry\").Recipes\n\nlocal shapedId = Recipes:RegisterShaped(\"signal_lantern\", {\n    pattern = { \"III\", \"ITI\", \" S \" },\n    key = {\n        I = \"minecraft:iron_ingot\",\n        T = \"minecraft:torch\",\n        S = \"minecraft:stick\",\n    },\n    result = { item = \"myaddon:signal_lantern\", count = 1 },\n})\n\nlocal shapelessId = Recipes:RegisterShapeless(\"scrap_bundle\", {\n    ingredients = { \"myaddon:metal_scrap\", \"#minecraft:coal\" },\n    result = \"myaddon:charred_scrap\",\n})\nprint(shapedId, shapelessId)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Recipes", "Register smithing upgrades and trims",
                "Use RegisterSmithingTransform for an item upgrade and RegisterSmithingTrim for an armor trim. Ingredients accept an item id, #tag selector, or definition table; use items = { ... } when one ingredient slot should accept several item ids. MLua validates these forms and writes ingredient and output formats for the active Minecraft version.",
                "local Recipes = Minecraft:GetService(\"Registry\").Recipes\n\nRecipes:RegisterSmithingTransform(\"reinforced_blade\", {\n    template = \"minecraft:netherite_upgrade_smithing_template\",\n    base = { items = { \"myaddon:steel_sword\", \"myaddon:iron_sword\" } },\n    addition = \"myaddon:echo_ingot\",\n    result = \"myaddon:echo_blade\",\n})\n\nRecipes:RegisterSmithingTrim(\"ashen_trim\", {\n    template = \"myaddon:ashen_smithing_template\",\n    base = \"#minecraft:trimmable_armor\",\n    addition = \"#minecraft:trim_materials\",\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Recipes", "Register a vanilla recipe type directly",
                "Registry.Recipes:Register accepts a Lua table or a JSON string. Use it for vanilla recipe types that do not have a dedicated Recipe builder; keep the fields aligned with the Minecraft version you target. Every recipe registration method returns its full addon namespaced id. Lua definitions are limited to 16,384 total table entries, 64 nested tables, and 1,048,576 characters of string content; raw JSON strings are limited to 1,048,576 characters.",
                "local Recipes = Minecraft:GetService(\"Registry\").Recipes\n\nlocal recipeId = Recipes:Register(\"armor_trim\", {\n    type = \"minecraft:smithing_trim\",\n    template = { item = \"minecraft:coast_armor_trim_smithing_template\" },\n    base = { tag = \"minecraft:trimmable_armor\" },\n    addition = { tag = \"minecraft:trim_materials\" },\n})\nprint(recipeId) -- myaddon:armor_trim"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry", "Work with registry entries generically",
                "Built-in category tables and the root Registry lookup share the same addon-local ID resolver. Get returns one live RegistryEntry; GetAll returns an ID-keyed map and GetIds returns a sorted array. GetRegistered and GetEntries remain available when you want explicit names. RegistryEntry.new takes a full namespaced identifier and returns the same class.",
                "local Registry = Minecraft:GetService(\"Registry\")\nlocal bow = Registry.Items:Get(\"bow\")\nlocal rootBow = Registry:Get(\"items\", \"bow\")\nlocal stone = Registry.Blocks:Get(\"minecraft:stone\")\nlocal fullyQualified = RegistryEntry.new(\"items\", bow.Id)\n\nprint(Registry.Items:GetId(\"bow\"))\nprint(bow.Kind, bow.Id, Registry:Exists(\"items\", \"bow\"))\nprint(rootBow:Equals(fullyQualified))\nif stone.IsRegistered then\n    print(stone.Namespace, stone.Path)\nend\n\nfor _, id in ipairs(Registry:GetIds(\"items\", \"myaddon\")) do\n    print(id)\nend\nfor id, entry in pairs(Registry:GetAll(\"items\", \"myaddon\")) do\n    print(id, entry.IsRegistered)\nend\n\nfor _, kind in ipairs(Registry:GetKinds()) do\n    print(kind)\nend"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Containers", "Attach storage to a scripted block",
                "The block entity keeps its slots on the server and opens a vanilla chest screen when the player interacts. AllowedItems is an optional allowlist applied to inventory slot insertion.",
                "Registry.Blocks:Register(\"supply_crate\", {\n    Container = \"supply_crate\",\n    onRightClick = function(context)\n        local container = context.Block:GetContainer()\n        if container and container:IsEmpty() then\n            container:SetSlot(1, { Id = \"minecraft:torch\", Count = 1 })\n        end\n    end,\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Blocks", "Build a timed scripted block",
                "onStepOn runs on the server. ScheduleTick waits the requested number of game ticks, then calls onTick with the live Block instance. Schedule another tick from onTick to build a repeating behavior.",
                "Registry.Blocks:Register(\"crumbling_stone\", {\n    copy = \"minecraft:stone\",\n    copyModel = true,\n    onStepOn = function(context)\n        context.Block:ScheduleTick(40) -- two seconds\n    end,\n    onTick = function(context)\n        context.Block:Set(\"minecraft:air\")\n    end,\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Items", "Discover available item types",
                "GetTypes returns the registered item kind names and short descriptions, including types added by Java extensions. The shovel spelling is canonical; spade remains an accepted alias.",
                "local Registry = Minecraft:GetService(\"Registry\")\nfor name, description in pairs(Registry.Items:GetTypes()) do\n    print(name, description)\nend\n\nRegistry.Blocks:GetTypes() -- lists default and Java-registered block types"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Items", "Define a reusable Lua content type",
                "RegisterType creates a reusable kind owned by your addon. It can extend a built-in or Java-registered type, and it can extend another addon's type by using its full namespace:name. Defaults merge recursively, so a definition can override one nested setting while inheriting the rest. Pass ItemProperties directly as Defaults to reuse the same chainable settings. The item uses Minecraft's native bow behavior and animation, while the default onUse callback can connect it to a projectile definition.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nRegistry.Items:RegisterType(\"hunting_bow\", {\n    Base = \"bow\",\n    Description = \"A reusable hunting bow with a custom shot.\",\n    Defaults = Registry.Items:Properties()\n        :Kind(\"bow\")\n        :StacksTo(1)\n        :Durability(420)\n        :Copy(\"minecraft:bow\")\n        :CopyModel(true)\n        :Description(\"A quiet weapon for the dark.\"),\n})\n\nRegistry.Items:Register(\"watcher_bow\", {\n    kind = \"hunting_bow\",\n    onUse = function(context)\n        -- Fire an addon projectile or apply custom effects here.\n    end,\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry", "Resolve inherited type defaults",
                "ResolveType applies the same inheritance and merge rules used during registration. Use the category method when you already know the category, or the Registry method when the category comes from data.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal definition = { kind = \"hunting_bow\", durability = 500 }\nlocal resolved = Registry.Items:ResolveType(definition)\n-- Equivalent when the category is dynamic:\nlocal resolvedAgain = Registry:ResolveType(\"items\", definition)\nprint(resolved.maxStackSize, resolved.durability)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Entities", "Reuse an entity archetype",
                "Entity type defaults use the same generic registry type system. The live entity still gets its own independent AI state and scripted callbacks.",
                "Registry:RegisterType(\"entities\", \"stalker_base\", {\n    Base = \"entity\",\n    Description = \"Shared physical defaults for stalker mobs.\",\n    Defaults = {\n        category = \"monster\",\n        width = 0.7,\n        height = 2.1,\n        attributes = { maxHealth = 36, movementSpeed = 0.28, attackDamage = 5 },\n    },\n})\n\nRegistry.Entities:Register(\"stalker\", {\n    RegistryType = \"stalker_base\",\n    onSpawn = function(self)\n        self:SetData({ alerted = false })\n    end,\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Items", "Register food and a native animated bow",
                "Food uses Minecraft's nutrition and saturation values, and onConsume runs once on the server. Set the item kind to bow to use Minecraft's native draw animation, charge timing, ammunition checks, and release behavior. Copying the vanilla bow model preserves its pull stages.",
                "Registry.Items:Register(\"haunted_ration\", {\n    food = { nutrition = 6, saturation = 0.8, alwaysEdible = true },\n    onConsume = function(context)\n        if context.Player then\n            context.Player:SendMessage(\"The ration tastes strangely warm.\")\n        end\n    end,\n})\n\nRegistry.Items:Register(\"ember_bow\", {\n    kind = \"bow\",\n    copy = \"minecraft:bow\", copyModel = true,\n    durability = 384, maxStackSize = 1,\n    description = \"A native animated bow with Minecraft arrow handling.\",\n})"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Entities", "Choose the mob's type settings",
                "Start with a Lua definition for the shared entity type. Each spawned mob is a separate live ScriptedEntity instance.",
                "local stalkerDefinition = {\n    category = \"monster\",\n    attributes = { maxHealth = 30, movementSpeed = 0.28, attackDamage = 4 }\n}"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Entities", "Build a mob type with chained settings",
                "EntityProperties uses the same chainable style as the item and block property classes. Attribute methods write into the entity's native attribute set; AI and lifecycle methods attach the scripted behavior used by each spawned mob.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal stalker = Registry.Entities:Properties()\n    :Category(\"monster\")\n    :Size(0.7, 2.1)\n    :TrackingRange(12)\n    :MaxHealth(36)\n    :MovementSpeed(0.28)\n    :AttackDamage(5)\n    :AI({\n        initial = \"Search\",\n        states = {\n            Search = {\n                update = function(self)\n                    local player = self:FindNearestPlayer(16, true)\n                    if player then\n                        self:AttackTarget(player)\n                        return \"Chase\"\n                    end\n                end\n            },\n            Chase = {\n                update = function(self)\n                    local target = self:GetTarget()\n                    if not target then return \"Search\" end\n                    self:LookAt(target.Position)\n                    self:MoveTo(target.Position, 1.0)\n                end\n            }\n        }\n    })\n\nRegistry.Entities:Register(\"stalker\", stalker)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Entities", "Give each mob an inherited Lua class",
                "Define a class that extends ScriptedEntity, then set className on the entity definition. Every spawned mob of that type receives the registered subclass, so its methods and mixins are available to AI and lifecycle callbacks.",
                "Minecraft:RegisterClass(\"Stalker\", \"ScriptedEntity\", \"A scripted stalker mob.\")\nMinecraft:RegisterClassFunction(\"Stalker\", \"Investigate\", function(self, position)\n    return self:MoveTo(position, 1.1)\nend, \"Moves the stalker to investigate a position.\")\n\nlocal stalkerDefinition = {\n    className = \"Stalker\",\n    AI = {\n        initial = \"Search\",\n        states = {\n            Search = {\n                update = function(self)\n                    local target = self:FindNearestPlayer(16, true)\n                    if target then\n                        self:Investigate(target.Position)\n                        return \"Chase\"\n                    end\n                end\n            },\n            Chase = {\n                update = function(self)\n                    local target = self:GetTarget()\n                    if not target or not target:GetIsAlive() then\n                        self:StopMoving()\n                        return \"Search\"\n                    end\n                    self:LookAt(target.Position)\n                    self:MoveTo(target.Position, 1.1)\n                end\n            }\n        }\n    }\n}\n\nRegistry.Entities:Register(\"stalker\", stalkerDefinition)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Entities", "Give the live entity behavior",
                "Add AI to the definition before registering it. MLua snapshots the state tables at registration, so later edits to the source table do not silently change a live entity type; register a new definition during startup to change it. Callbacks receive the actual mob as self, with ScriptedEntity, LivingEntity, and Entity methods. An update callback's optional second argument is a per-tick snapshot containing State, TicksInState, and Target; edit it only for callback-local logic. Use self:SetAIState(name) or return a declared state name to change the live state. Keep decisions in state updates; navigation continues between AI updates. State tables can define onEnter and onExit hooks. An update returns nil to stay in its state or a declared state name to transition. Invalid return values disable only that state's update callback; a failing transition hook is disabled independently. AI definitions must use plain acyclic tables because MLua snapshots raw table data; metatables and cyclic tables are rejected. Each definition supports up to 256 states, and state names are limited by ScriptDefinitionLimits.MaxBehaviorNameLength. Nested AI tables are also bounded by MaxEntityAITableEntries and MaxEntityAITableDepth.",
                "stalkerDefinition.AI = {\n    initial = \"Search\",\n    states = {\n        Search = {\n            update = function(self, ai)\n                local player = self:FindNearestPlayer(16, true)\n                if player then\n                    self:AttackTarget(player)\n                    return \"Chase\"\n                end\n            end\n        },\n        Chase = {\n            update = function(self, ai)\n                local target = self:GetTarget()\n                if not target or not target:GetIsAlive() then\n                    self:AttackTarget(nil)\n                    return \"Search\"\n                end\n                self:LookAt(target.Position)\n                self:MoveTo(target.Position, 1.0)\n                if self:DistanceTo(target) <= 2.5 then\n                    self:MeleeAttack(target, 24)\n                end\n            end\n        }\n    }\n}\nRegistry.Entities:Register(\"stalker\", stalkerDefinition)"));
        docs.register(MLuaDocBuilder.Registration.guideStep("Registry.Entities", "Spawn an instance",
                "Spawn the registered type on the server through EntityService. The returned entity is managed by Minecraft and uses the callbacks registered for its type. BehaviorKey identifies the scripted definition; the inherited Type property keeps its Minecraft entity type meaning.",
                "local EntityService = Minecraft:GetService(\"EntityService\")\nlocal stalker = EntityService:Spawn(\"myaddon:stalker\", Vector3.new(12, 64, -8))\nif stalker then\n    print(stalker.BehaviorKey, stalker.Type)\n    stalker:SetData({ alerted = true })\nend"));
        docs.register(MLuaDocBuilder.Registration.guideStep("ScriptedEntity", "Handle damage and interaction",
                "Entity callbacks receive the live mob as self. onHurt runs after Minecraft accepts the damage, and onDeath receives the damage source id. Return false from onInteract to let Minecraft try its normal interaction; true or no return value consumes the interaction.",
                "stalkerDefinition.onHurt = function(self, amount, source)\n    print(self.Name, \"took\", amount, \"damage from\", source)\nend\n\nstalkerDefinition.onDeath = function(self, source)\n    print(self.Name, \"died to\", source)\nend\n\nstalkerDefinition.onInteract = function(self, player, hand)\n    self:SetAIState(\"Chase\")\n    return true\nend"));
        docs.register(MLuaDocBuilder.Registration.contribution(MLuaDocBuilder.Contribution.builder(MODULE_ID, "registry:scripted-mob-walkthrough")
            .section("Scripted mobs")
            .title("Build a mob with scripted AI")
            .description("Register the mob during startup, let the server drive its state machine, then spawn it into a world. The mob stays a native Minecraft entity; Lua supplies its decisions and callbacks.")
            .order(10)
            .step("Registry phase", "Register the entity and its states",
                "Put the registration in a .registry.lua script. Registration runs during startup, so use this phase to define the entity type and behavior. AI callbacks run on the server; keep world changes, navigation, and attacks there.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nRegistry.Entities:Register(\"stalker\", {\n    category = \"monster\",\n    width = 0.7,\n    height = 2.1,\n    attributes = { maxHealth = 36, movementSpeed = 0.28, attackDamage = 5 },\n    AI = {\n        initial = \"Search\",\n        states = {\n            Search = {\n                update = function(self)\n                    local target = self:FindNearestPlayer(16, true)\n                    if target then\n                        self:AttackTarget(target)\n                        return \"Chase\"\n                    end\n                end\n            },\n            Chase = {\n                update = function(self)\n                    local target = self:GetTarget()\n                    if not target or not target:GetIsAlive() then\n                        self:AttackTarget(nil)\n                        return \"Search\"\n                    end\n                    self:LookAt(target.Position)\n                    self:MoveTo(target.Position, 1.0)\n                    if self:DistanceTo(target) <= 2.5 then\n                        self:MeleeAttack(target, 24)\n                    end\n                end\n            }\n        }\n    }\n})")
            .step("Server script", "Spawn it in a world",
                "Use the registered namespaced id from a server script. The returned value is the live ScriptedEntity instance, so you can inspect it or set initial persistent data. Handle a missing result instead of assuming the spawn succeeded.",
                "local EntityService = Minecraft:GetService(\"EntityService\")\nlocal stalker = EntityService:Spawn(\"myaddon:stalker\", Vector3.new(12, 64, -8))\n\nif stalker then\n    stalker:SetData({ alert = \"quiet\" })\n    print(stalker.BehaviorKey, stalker.Position)\nend")
            .step("Tune behavior", "Keep decisions separate from movement",
                "Return a declared state name when a decision changes; return nil to stay in the current state. Navigation continues between updates, so the mob does not need to calculate a new path every tick. Use onEnter and onExit for one-time state setup and cleanup.",
                "Chase = {\n    onEnter = function(self)\n        print(\"The stalker found a target\")\n    end,\n    update = function(self)\n        local target = self:GetTarget()\n        if not target or not target:GetIsAlive() then\n            self:StopMoving()\n            return \"Search\"\n        end\n        self:LookAt(target.Position)\n        self:MoveTo(target.Position, 1.0)\n    end,\n    onExit = function(self)\n        self:StopMoving()\n    end\n}")
            .build()));
        docs.register(MLuaDocBuilder.Registration.contribution(MLuaDocBuilder.Contribution.builder(MODULE_ID, "registry:container-block-walkthrough")
            .section("Blocks and containers")
            .title("Build a block with a usable container")
            .description("Register the block, its inventory layout, and its saved block entity together during the registry phase. Minecraft owns the block and screen; Lua supplies the definition and server-side behavior.")
            .order(20)
            .step("Registry script", "Choose the container layout",
                "Container rows set the vanilla chest-style inventory size. Register the layout separately when you want to reuse it, or use an inline definition on the block.",
                "local Registry = Minecraft:GetService(\"Registry\")\n\nlocal workbench = Registry.Containers:Register(\"field_workbench\", {\n    rows = 2,\n    title = \"Field Workbench\"\n})")
            .step("Registry script", "Attach state and behavior to the block",
                "Continue in the same registry file. Register a BlockEntity subclass for persistent state, then reference both it and the container in the block definition. The onLoad callback receives the live subclass as self; its Nbt data is saved with the block entity. Restart Minecraft after changing registry definitions.",
                "Minecraft:RegisterClass(\"FieldWorkbenchEntity\", \"BlockEntity\", \"Saved state for a field workbench.\")\n\nRegistry.Blocks:Register(\"field_workbench\", {\n    strength = 3,\n    container = workbench,\n    blockEntity = {\n        className = \"FieldWorkbenchEntity\",\n        onLoad = function(self)\n            self.Nbt.uses = self.Nbt.uses or 0\n        end,\n        onOpen = function(self, context)\n            self.Nbt.uses = self.Nbt.uses + 1\n            if context.Player then\n                context.Player:SendMessage(\"Workbench use: \" .. self.Nbt.uses)\n            end\n        end\n    }\n})")
            .step("In game", "Read the live block entity when needed",
                "World:GetBlock returns the live block wrapper. GetBlockEntity gives you the same attached instance used by the callbacks, so methods added to FieldWorkbenchEntity can encapsulate state changes.",
                "local World = Minecraft:GetService(\"World\")\nlocal block = World:GetBlock(Vector3.new(12, 64, -8))\nlocal entity = block and block:GetBlockEntity()\nif entity then\n    print(entity.Nbt.uses or 0, entity.Position)\nend")
            .build()));
